#![cfg(feature="sqlite")]
use cyclecare_core::{local_repository::*,local_commit_store::{Error,Outcome,ScratchStore,SyncInput},local_commit_plan::Identity,sync_codec as c};
fn id()->Identity{Identity{namespace:"legacy_guest".into(),effective:"device-effective".into(),instance:"dbguest".into(),epoch:1,session:1,generation:3,local:true}}
fn log()->c::CycleDayLog{let mut l=cyclecare_core::track_log::CycleDayLog::new("2024-03-17");l.notes="x".into();l.bbt_celsius=-0.0;(&l).into()}
fn sync(ids:Vec<&str>)->SyncInput{SyncInput{owner:"legacy_guest".into(),generation:3,now_ms:1234,operation_ids:ids.into_iter().map(str::to_string).collect()}}
#[test]
fn sync_composition_preserves_ack_and_pending_semantics(){let i=id();let s=ScratchStore::new_memory(&i).unwrap();s.inject_sql_for_test("INSERT INTO health_sync_revisions VALUES('legacy_guest','2024-03-17',7,'old',0,1,5); INSERT INTO health_sync_outbox VALUES('legacy_guest','old','2024-03-17','UPSERT',4,7,'old','old',2,4,99,'retry','server-ok',5);").unwrap();let l=log();let p=s.prepare_save_sync_for_test(&i,"op",&l,sync(vec!["child-log","child-settings"])).unwrap();s.commit(&p).unwrap();s.inject_sql_for_test("CREATE TEMP TABLE a(ok INTEGER CHECK(ok=1)); INSERT INTO a SELECT COUNT(*) FROM health_sync_revisions WHERE ownerId='legacy_guest' AND recordId='2024-03-17' AND revision=8 AND serverRevision=5 AND tombstone=0; INSERT INTO a SELECT COUNT(*) FROM health_sync_outbox WHERE operationId='child-log' AND revision=8 AND baseRevision=5 AND consentGeneration=3 AND attempts=0 AND nextAttemptAt=0 AND serverReceipt IS NULL AND serverRevision IS NULL; INSERT INTO a SELECT COUNT(*) FROM health_sync_outbox WHERE operationId='old' AND serverReceipt='server-ok' AND attempts=4 AND nextAttemptAt=99;").unwrap();assert!(matches!(s.commit(&p).unwrap(),Outcome::Committed{replay:true,..}));let d=s.prepare_delete_sync_for_test(&i,"delete",&l.date,sync(vec!["child-delete"])).unwrap();s.commit(&d).unwrap();s.inject_sql_for_test("INSERT INTO a SELECT COUNT(*) FROM health_sync_revisions WHERE recordId='2024-03-17' AND revision=9 AND tombstone=1 AND payloadHash IS NULL AND serverRevision=5; INSERT INTO a SELECT COUNT(*) FROM health_sync_outbox WHERE operationId='child-delete' AND kind='DELETE' AND payloadJson IS NULL AND baseRevision=5 AND revision=9;").unwrap();}
#[test]
fn sync_overflow_collision_and_drift_rollback_all(){let i=id();for mode in 0..3{let s=ScratchStore::new_memory(&i).unwrap();if mode==0{s.inject_sql_for_test("INSERT INTO health_sync_revisions VALUES('legacy_guest','2024-03-17',9223372036854775807,'old',0,1,5);").unwrap();}if mode==1{s.inject_sql_for_test("INSERT INTO health_sync_outbox VALUES('legacy_guest','child-log','other','UPSERT',0,1,'old','old',2,4,99,'retry','server-ok',5);").unwrap();}let l=log();let p=s.prepare_save_sync_for_test(&i,"op",&l,sync(vec!["child-log","child-settings"])).unwrap();if mode==2{s.inject_sql_for_test("INSERT INTO health_sync_revisions VALUES('legacy_guest','2024-03-17',1,'drift',0,1,0);").unwrap();}assert_eq!(s.commit(&p),Err(if mode==0{Error::Overflow}else if mode==1{Error::Storage}else{Error::Conflict}));assert!(s.log(&l.date).unwrap().is_none());assert!(s.settings().unwrap().is_none());}}
#[test]
fn routed_reads_writes_signedzero_session_and_aba(){let i=id();let r=Repository::new_synthetic(i.clone(),"legacy_guest".into()).unwrap();let t=r.capture().unwrap();let l=log();let p=r.prepare_save(&t,"op",&l,1,vec!["a".into(),"b".into()]).unwrap();r.commit(&t,&p).unwrap();let snapshot=r.read(&t,&l.date).unwrap();assert_eq!(snapshot.log.as_ref().unwrap().bbt_celsius.to_bits(),0x80000000);assert!(r.accept(&snapshot).unwrap());let mut b=i.clone();b.namespace="owner-B".into();b.effective="owner-B".into();b.instance="dbB".into();b.epoch=2;b.local=false;let bt=r.transition(&t,b,"owner-B".into()).unwrap();assert_eq!(r.read(&t,&l.date).unwrap_err(),Error::Stale);assert_eq!(r.commit(&t,&p),Err(Error::Stale));assert!(!r.accept(&snapshot).unwrap());assert!(r.read(&bt,&l.date).unwrap().log.is_none());let mut back=i;back.epoch=3;back.session=2;let at=r.transition(&bt,back,"legacy_guest".into()).unwrap();assert_eq!(r.commit(&t,&p),Err(Error::Stale));assert_eq!(r.read(&at,&l.date).unwrap().log.unwrap().bbt_celsius.to_bits(),0x80000000);}
#[test]
fn explicit_consent_generation_drift_rejects_prepared(){let i=id();let r=Repository::new_synthetic(i.clone(),"legacy_guest".into()).unwrap();let t=r.capture().unwrap();let p=r.prepare_save(&t,"op",&log(),1,vec!["a".into(),"b".into()]).unwrap();let mut next=i;next.epoch+=1;next.generation+=1;let nt=r.transition(&t,next,"legacy_guest".into()).unwrap();assert_eq!(r.commit(&t,&p),Err(Error::Stale));assert!(r.read(&nt,"2024-03-17").unwrap().log.is_none());}
#[test]
fn profile_derived_first_settings_and_stale_profile_read(){let i=id();let s=ScratchStore::new_memory(&i).unwrap();s.inject_sql_for_test("INSERT INTO onboarding_profiles VALUES(1,1,123,1,1,'LOCAL','health','2024-02-01','','EXACT','30 days',30,6,1,'','','',0);").unwrap();let p=s.prepare_save_sync_for_test(&i,"op",&log(),sync(vec!["log","settings"])).unwrap();s.inject_sql_for_test("UPDATE onboarding_profiles SET cycleLengthDays=31").unwrap();assert_eq!(s.commit(&p),Err(Error::Conflict));let p=s.prepare_save_sync_for_test(&i,"op2",&log(),sync(vec!["log2","settings2"])).unwrap();s.commit(&p).unwrap();let settings=s.settings().unwrap().unwrap();assert!(settings.is_onboarding_completed&&settings.remind_fertile);assert_eq!(settings.average_cycle_length,31);assert_eq!(settings.period_duration,6);assert_eq!(settings.last_period_start_date,"2024-02-01");}
#[test]
fn real_threads_commit_then_switch_and_switch_then_commit(){use std::sync::{Arc,mpsc};for switch_first in [false,true]{let i=id();let r=Arc::new(Repository::new_synthetic(i.clone(),"legacy_guest".into()).unwrap());let t=r.capture().unwrap();let p=r.prepare_save(&t,"op",&log(),1,vec!["a".into(),"b".into()]).unwrap();let (tx,rx)=mpsc::channel();let worker=r.clone();let token=t.clone();let handle=std::thread::spawn(move||{rx.recv().unwrap();worker.commit(&token,&p)});let mut next=i;next.session+=1;next.epoch+=1;if switch_first{let nt=r.transition(&t,next,"legacy_guest".into()).unwrap();tx.send(()).unwrap();assert_eq!(handle.join().unwrap(),Err(Error::Stale));assert!(r.read(&nt,"2024-03-17").unwrap().log.is_none());}else{tx.send(()).unwrap();assert!(matches!(handle.join().unwrap().unwrap(),Outcome::Committed{replay:false,..}));let nt=r.transition(&t,next,"legacy_guest".into()).unwrap();assert_eq!(r.read(&nt,"2024-03-17").unwrap().log.unwrap().bbt_celsius.to_bits(),0x80000000);}}}
